<?php
declare(strict_types=1);

require dirname(__DIR__).'/app/bootstrap.php';$user=require_role('admin');
$status=(string)($_GET['status']??'');$allowed=['open','matched','in_progress','completed','cancelled'];$where='1=1';$params=[];if(in_array($status,$allowed,true)){$where='r.status=?';$params[]=$status;}
$statement=db()->prepare("SELECT r.id,r.title,r.status,r.created_at,c.name category_name,d.name district_name,u.full_name client_name,COUNT(p.id) proposal_count FROM service_requests r JOIN categories c ON c.id=r.category_id JOIN districts d ON d.id=r.district_id JOIN users u ON u.id=r.client_id LEFT JOIN proposals p ON p.request_id=r.id WHERE $where GROUP BY r.id,r.title,r.status,r.created_at,c.name,d.name,u.full_name ORDER BY r.created_at DESC LIMIT 200");$statement->execute($params);$rows=$statement->fetchAll();
$pageTitle='Solicitudes';$pageSubtitle='Moderación y seguimiento';$activeDashboard='requests';require dirname(__DIR__).'/templates/dashboard-header.php';
?>
<div class="page-head"><div><h2>Solicitudes del marketplace</h2><p><?=count($rows)?> resultados mostrados</p></div></div><form class="filter-bar" method="get"><div class="field"><label for="status">Estado</label><select id="status" name="status" data-auto-submit><option value="">Todos</option><?php foreach($allowed as $option):?><option value="<?=e($option)?>"<?=selected($status,$option)?>><?=e(status_label($option))?></option><?php endforeach;?></select></div><div></div><button class="btn btn-secondary">Filtrar</button></form>
<section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Solicitud</th><th>Cliente</th><th>Categoría</th><th>Propuestas</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td class="table-title"><strong><?=e($row['title'])?></strong><span><?=e($row['district_name'])?> · <?=e(date_pe($row['created_at']))?></span></td><td><?=e($row['client_name'])?></td><td><?=e($row['category_name'])?></td><td><?=(int)$row['proposal_count']?></td><td><span class="status status-<?=e(status_class($row['status']))?>"><?=e(status_label($row['status']))?></span></td><td><div class="table-actions"><a class="btn btn-secondary btn-small" href="<?=e(url('request-view.php?id='.(int)$row['id']))?>">Ver</a><form action="<?=e(url('actions.php'))?>" method="post"><?=csrf_field()?><input type="hidden" name="action" value="admin_request_status"><input type="hidden" name="request_id" value="<?=(int)$row['id']?>"><select name="status" aria-label="Cambiar estado"><?php foreach($allowed as $option):?><option value="<?=e($option)?>"<?=selected($row['status'],$option)?>><?=e(status_label($option))?></option><?php endforeach;?></select><button class="btn btn-ghost btn-small">Aplicar</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require dirname(__DIR__).'/templates/dashboard-footer.php';?>
